import { run, step } from "zttp:durable";

structural DurableOrderProof<T> = Proof<T, ...>;

function handler(req: Request): DurableOrderProof<Response> {
  const key = req.headers.get("idempotency-key") ?? "order-default";
  return run(key, () => {
    const reservation = step("reserve", () => {
      // reserve inventory
      return { reserved: true, ... };
    });
    if (!reservation.reserved) return Response.json({ error: "reservation failed" }, { status: 409 });
    const charge = step("charge", () => {
      // charge payment
      return { charged: true, ... };
    });
    if (!charge.charged) return Response.json({ error: "charge failed" }, { status: 402 });
    return Response.json({ reserved: true, charged: true }, { status: 201 });
  });
}
```

